package aurora

import (
	"embed"
	"encoding/json"
	"fmt"
	"path"
	"slices"
	"strings"
)

// expertBundle holds the vendored octop expert library: one directory per
// SkillHub skillset, generated by scripts/aurora-import-experts.mjs. The
// generator's --check mode keeps the tree byte-identical to the upstream
// snapshot; nothing here is edited by hand.
//
//go:embed experts
var expertBundle embed.FS

const (
	expertRoot        = "experts"
	expertIndexPath   = "experts/index.json"
	expertWorkflow    = "workflow.md"
	expertSubskillDir = "subskills"
)

// Expert is one vendored SkillHub skillset: the persona, the skillset workflow
// and the sub-skills the workflow orchestrates.
type Expert struct {
	Slug          string `json:"slug"`
	NameZh        string `json:"name_zh"`
	NameEn        string `json:"name_en"`
	Scene         string `json:"scene"`
	DescriptionZh string `json:"description_zh"`
	DescriptionEn string `json:"description_en"`
	// MissingSubskills names sub-skill directories the upstream download left
	// empty (marketing-social-media-operation ships an empty content-writer).
	MissingSubskills []string            `json:"missing_subskills"`
	QuickPrompts     []ExpertQuickPrompt `json:"quick_prompts"`
	Subskills        []ExpertSubskill    `json:"subskills"`
}

// ExpertQuickPrompt is one upstream quick-start card: a label and a
// fill-in-the-blanks prompt, in both languages. The seeder maps the first ones
// onto the agent's conversation starters.
type ExpertQuickPrompt struct {
	LabelZh  string `json:"label_zh"`
	LabelEn  string `json:"label_en"`
	PromptZh string `json:"prompt_zh"`
	PromptEn string `json:"prompt_en"`
}

// ExpertSubskill is one sub-skill of an expert. Name is the workspace-unique
// skill name ("<expert>--<sub>"); Files lists every file under the sub-skill
// directory, including its SKILL.md.
type ExpertSubskill struct {
	Slug      string       `json:"slug"`
	Name      string       `json:"name"`
	DisplayZh string       `json:"display_zh"`
	DisplayEn string       `json:"display_en"`
	Files     []ExpertFile `json:"files"`
}

// ExpertFile describes one vendored file. Size and SHA256 are provenance only;
// the seeding path reads the file itself.
type ExpertFile struct {
	Path   string `json:"path"`
	Size   int    `json:"size"`
	SHA256 string `json:"sha256"`
}

// ExpertFileContent is one sub-skill supporting file, path relative to the
// sub-skill's own directory.
type ExpertFileContent struct {
	Path    string
	Content string
}

// ExpertSubskillContent is one sub-skill: the SKILL.md body the skill row
// carries, and the supporting files the skill_file rows carry.
type ExpertSubskillContent struct {
	Content string
	Files   []ExpertFileContent
}

type expertIndex struct {
	Schema  int      `json:"schema"`
	Source  string   `json:"source"`
	Experts []Expert `json:"experts"`
}

// expertLibrary is parsed once at init: it is compiled-in data, so a parse
// failure is a build-time defect and panics the way a broken embed would.
var expertLibrary = mustLoadExpertLibrary()

func mustLoadExpertLibrary() expertIndex {
	raw, err := expertBundle.ReadFile(expertIndexPath)
	if err != nil {
		panic(fmt.Sprintf("aurora: read expert index: %v", err))
	}
	var index expertIndex
	if err := json.Unmarshal(raw, &index); err != nil {
		panic(fmt.Sprintf("aurora: parse expert index: %v", err))
	}
	if len(index.Experts) == 0 {
		panic("aurora: expert index is empty")
	}
	return index
}

// Experts returns an independent copy of the vendored expert index.
func Experts() []Expert {
	out := make([]Expert, len(expertLibrary.Experts))
	for i, expert := range expertLibrary.Experts {
		out[i] = cloneExpert(expert)
	}
	return out
}

// ExpertBySlug returns an independent copy of one expert.
func ExpertBySlug(slug string) (Expert, bool) {
	for _, expert := range expertLibrary.Experts {
		if expert.Slug == slug {
			return cloneExpert(expert), true
		}
	}
	return Expert{}, false
}

// ExpertWorkflow returns the generated Aurora brief for an expert. The returned
// string is a copy the caller owns.
func ExpertWorkflow(slug string) (string, bool) {
	if !validExpertSlug(slug) {
		return "", false
	}
	if _, ok := ExpertBySlug(slug); !ok {
		return "", false
	}
	raw, err := expertBundle.ReadFile(path.Join(expertRoot, slug, expertWorkflow))
	if err != nil {
		return "", false
	}
	brief := strings.TrimSpace(string(raw))
	if brief == "" {
		return "", false
	}
	return brief, true
}

// LoadExpertSubskill loads one sub-skill's SKILL.md body and its supporting
// files. SKILL.md is never repeated in Files: writeSkillFiles treats it as
// reserved content anyway (skillpkg.IsReservedContentPath).
func LoadExpertSubskill(expertSlug, subSlug string) (ExpertSubskillContent, bool) {
	if !validExpertSlug(expertSlug) || !validExpertSlug(subSlug) {
		return ExpertSubskillContent{}, false
	}
	expert, ok := ExpertBySlug(expertSlug)
	if !ok {
		return ExpertSubskillContent{}, false
	}
	var sub ExpertSubskill
	for _, candidate := range expert.Subskills {
		if candidate.Slug == subSlug {
			sub = candidate
			break
		}
	}
	if sub.Slug == "" {
		return ExpertSubskillContent{}, false
	}
	dir := path.Join(expertRoot, expertSlug, expertSubskillDir, subSlug)
	content, err := expertBundle.ReadFile(path.Join(dir, "SKILL.md"))
	if err != nil {
		return ExpertSubskillContent{}, false
	}
	out := ExpertSubskillContent{Content: string(content)}
	for _, file := range sub.Files {
		if file.Path == "SKILL.md" || !validExpertFilePath(file.Path) {
			continue
		}
		body, err := expertBundle.ReadFile(path.Join(dir, file.Path))
		if err != nil {
			return ExpertSubskillContent{}, false
		}
		out.Files = append(out.Files, ExpertFileContent{Path: file.Path, Content: string(body)})
	}
	return out, true
}

// validExpertSlug rejects anything that could escape the embedded tree: slugs
// are directory names, never paths.
func validExpertSlug(slug string) bool {
	if slug == "" || strings.ContainsAny(slug, "/\\.") {
		return false
	}
	return !strings.Contains(slug, "..")
}

// validExpertFilePath rejects an index entry that names a path outside its
// sub-skill directory. The index is generated, but the guard is cheap.
func validExpertFilePath(filePath string) bool {
	if filePath == "" || strings.HasPrefix(filePath, "/") {
		return false
	}
	return !slices.Contains(strings.Split(filePath, "/"), "..")
}

func cloneExpert(expert Expert) Expert {
	expert.MissingSubskills = slices.Clone(expert.MissingSubskills)
	expert.QuickPrompts = slices.Clone(expert.QuickPrompts)
	subskills := make([]ExpertSubskill, len(expert.Subskills))
	for i, sub := range expert.Subskills {
		sub.Files = slices.Clone(sub.Files)
		subskills[i] = sub
	}
	expert.Subskills = subskills
	return expert
}
